def solve(s):
    """Run-length encoding: return list of [char, count] for consecutive runs."""
    result = []
    if not s:
        return result
    prev = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == prev:
            cnt += 1
        else:
            result.append([prev, cnt])
            prev = ch
            cnt = 1
    result.append([prev, cnt])
    return result

