    """Run-length encoding for any iterable of characters.
    Returns a list of [character, count] for consecutive runs.
    If *s* is not iterable, returns an empty list.
    """
    try:
        chars = list(s)
    except TypeError:
        return []
    if not chars:
        return []
    result = []
    prev = chars[0]
    cnt = 1
    for ch in chars[1:]:
        if ch == prev:
            cnt += 1
        else:
            result.append([prev, cnt])
            prev = ch
            cnt = 1
    result.append([prev, cnt])
