def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Tokens are strings representing integers or the operators '+', '-', '*', '/'.
    Division truncates toward zero (e.g., -3/2 -> -1).
    """
    def trunc_div(a, b):
        # Perform integer division truncating toward zero without using float.
        if b == 0:
            raise ZeroDivisionError("division by zero")
        sign = -1 if (a < 0) ^ (b < 0) else 1
        return sign * (abs(a) // abs(b))

    stack = []
    ops = {'+', '-', '*', '/'}
    for token in tokens:
        if token in ops:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # '/'
                res = trunc_div(a, b)
            stack.append(res)
        else:
            # Accept token as int or string representation
            try:
                stack.append(int(token))
            except Exception:
                # If token is already an int
                stack.append(token)
    return stack[0] if stack else 0

