def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting algorithm with O(n log n) time.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find insertion point
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

