    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            # neighbors: up, down, left, right
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                    if not visited[nr][nc] and grid[nr][nc] == 1:
