def solve(grid):
    """Return number of islands in a 2D grid of 0s and 1s.
    Handles non‑rectangular grids and empty rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Use a set for visited cells to handle varying row lengths
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            # Bounds check for current row length
            if i < 0 or i >= rows:
                continue
            if j < 0:
                continue
            if j >= len(grid[i]):
                continue
            if (i, j) in visited:
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            # Push neighbours
            stack.append((i-1, j))
            stack.append((i+1, j))
